#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""将 spanish_raw.json 生成为 src/data/spanishLexicon.ts"""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from es_zh_map import get_zh  # noqa: E402

RAW = Path(r'D:\ielts-lexicon\scripts\spanish_raw.json')
OUT = Path(r'D:\ielts-lexicon\src\data\spanishLexicon.ts')


def esc(s: str) -> str:
    return s.replace('\\', '\\\\').replace("'", "\\'")


def main():
    data = json.loads(RAW.read_text(encoding='utf-8'))
    lines = [
        '// AUTO-GENERATED by scripts/gen_spanish_ts.py from spanish_data-master.zip',
        '// 西语核心词库（Wiktionary es-en + Tatoeba 例句，CC-BY-SA）— 请勿手工编辑。',
        '// 收录高频 lemma ~19900 条，按词频降序（frequencyRank）。',
        '',
        'export interface SpanishLexEntry {',
        '  /** 词性（西语缩写：n./v./adj./adv./prep....） */',
        '  pos: string;',
        '  /** 英文主释义（Wiktionary gloss） */',
        '  translation: string;',
        '  /** 中文释义（高频核心词精校；其余由英文 gloss 兜底） */',
        '  chineseTranslation: string;',
        '  /** 英文次释义（第二个 gloss，可空） */',
        '  englishDefinition: string;',
        '  /** 词频排名（1 = 最高频） */',
        '  frequencyRank: number;',
        '  /** 西语例句 1（Tatoeba，最短） */',
        '  example: string;',
        '  /** 例句 1 英文翻译 */',
        '  exampleTranslation: string;',
        '  /** 西语例句集合（按句长升序，最多 5 条） */',
        '  examples: [string, string][];',
        '  /** 固定搭配（精校 + 短句提取） */',
        '  phrases: [string, string][];',
        '}',
        '',
        'export const SPANISH_LEXICON: Record<string, SpanishLexEntry> = {',
    ]
    n = 0
    seen = set()
    for e in data:
        word = e['word'].strip()
        if not word or not e['translation']:
            continue
        key = word.lower()
        if key in seen:
            continue
        seen.add(key)
        examples = e.get('examples', []) or []
        phrases = e.get('phrases', []) or []
        # 序列化为内嵌 JS 数组字面量
        ex_lit = '[' + ', '.join(f"['{esc(es)}', '{esc(en)}']" for es, en in examples) + ']'
        ph_lit = '[' + ', '.join(f"['{esc(ps)}', '{esc(pz)}']" for ps, pz in phrases) + ']'
        lines.append(
            f"  '{esc(key)}': {{ pos: '{esc(e['pos'])}', translation: '{esc(e['translation'])}', "
            f"chineseTranslation: '{esc(get_zh(key))}', "
            f"englishDefinition: '{esc(e['englishDefinition'])}', frequencyRank: {e['frequencyRank']}, "
            f"example: '{esc(e['example'])}', exampleTranslation: '{esc(e['exampleTranslation'])}', "
            f"examples: {ex_lit}, phrases: {ph_lit} }},"
        )
        n += 1
    lines.append('};')
    lines.append('')
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text('\n'.join(lines), encoding='utf-8')
    print('entries written:', n)
    print('saved:', OUT)


if __name__ == '__main__':
    main()